#!/usr/bin/env python3
from pathlib import Path
import json,hashlib
ROOT=Path('/home/ubuntu/CHAOS'); G=ROOT/'campaigns/CAMPAIGN_SHARED_GATE_V1'
def load(rel):return json.loads((ROOT/rel).read_text())
def main():
 ds=load('campaigns/CAMPAIGN_SHARED_GATE_V1/DOMAIN_STATE_SCHEMA_VALIDATION_V1.json'); te=load('campaigns/CAMPAIGN_SHARED_GATE_V1/TRANSITION_EVIDENCE_SCHEMA_VALIDATION_V1.json'); sg=load('campaigns/CAMPAIGN_SHARED_GATE_V1/SUPERVISOR_GATE_DECISION_V1.json'); eg=load('experiments/macro_plus_eia_energy/evidence_graph_v1/EVIDENCE_GRAPH_SUMMARY.json'); pc=load('experiments/macro_plus_eia_energy/pattern_compiler_v1/PATTERN_COMPILER_SUMMARY.json')
 checks={'domain_state_schema_pass':ds.get('status')=='pass','transition_evidence_schema_pass':te.get('status')=='pass','supervisor_gate_pass':sg.get('status')=='pass','causal_claims_zero':sg.get('causal_claims_admitted')==0 and eg.get('causal_claims')==0 and pc.get('causal_claims')==0,'runtime_eligible_zero':pc.get('runtime_eligible')==0,'positive_status_restricted':sg.get('positive_composition_statuses')==['supported_predictive'],'rejected_quarantine_rule':all(sg['rules'].get(k) is False for k in ['rejected_positive_weight','unresolved_positive_weight','not_testable_positive_weight','provisional_descriptive_positive_weight'])}
 if not all(checks.values()): raise SystemExit(checks)
 result={'final_gate_id':'CHAOS_CAMPAIGN_SUPERVISOR_FINAL_GATE_V1','checks':checks,'admitted_supported_predictive_records':sg['admitted_supported_predictive_records'],'quarantined_records':sg['quarantined_records'],'graph_nodes':eg['node_count'],'graph_edges':eg['edge_count'],'compiled_runtime_eligible':pc['runtime_eligible'],'causal_claims':0,'decision':'admit_only_supported_predictive_to_shared_composition','market_intelligence_engine_modified':False,'status':'pass','input_hashes':{rel:hashlib.sha256((ROOT/rel).read_bytes()).hexdigest() for rel in ['campaigns/CAMPAIGN_SHARED_GATE_V1/DOMAIN_STATE_SCHEMA_VALIDATION_V1.json','campaigns/CAMPAIGN_SHARED_GATE_V1/TRANSITION_EVIDENCE_SCHEMA_VALIDATION_V1.json','campaigns/CAMPAIGN_SHARED_GATE_V1/SUPERVISOR_GATE_DECISION_V1.json','experiments/macro_plus_eia_energy/evidence_graph_v1/EVIDENCE_GRAPH_SUMMARY.json','experiments/macro_plus_eia_energy/pattern_compiler_v1/PATTERN_COMPILER_SUMMARY.json']}}
 (G/'FINAL_SUPERVISOR_ELIGIBILITY_GATE_V1.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps(result,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
